  ('ps-tan-hill-inn', 'photo', 'Tan Hill Inn', 'Britain''s highest pub at 1,732 ft on the moor road between Swaledale and Arkengarthdale, a well-known bikers'' stop on Dales rides.', private.pt(54.4556, -2.1603), null, null, null, 'North Yorkshire', array['Private car park: be respectful; security may move you on.', 'Exposed moorland road; snow closes it in winter.']::text[]),
