  ('ps-strines-inn-bradfield-dale', 'photo', 'Strines Inn, Bradfield Dale', 'Remote moorland pub on the twisting Strines road west of Sheffield, recommended as a stop on BestBikingRoads rides.', private.pt(53.4116, -1.6671), null, null, null, 'South Yorkshire', array['Private car park: be respectful; security may move you on.', 'Customers'' car park; narrow, steep road.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-bridlington-harbour-car-park', 'photo', 'Bridlington Harbour car park', 'Pay car park at the harbour by the South Pier and the start of South Bay. Adams Harbour Cafe on the pier is listed as a bikers'' meeting place, and South Marine Drive alongside hosts the Race the Waves hot rod and motorcycle show.', private.pt(54.0811, -0.1923), null, null, null, 'East Riding of Yorkshire', array['Pay parking; busy in summer.', 'South Marine Drive closes for the Race the Waves weekend.']::text[]),
  ('ps-seaways-cafe-fridaythorpe', 'photo', 'Seaways Cafe, Fridaythorpe', 'Long-running Wolds roadside cafe on the A166, open all year and listed as a bikers'' meeting place.', private.pt(54.0207, -0.6612), null, null, null, 'East Riding of Yorkshire', array['Private car park: be respectful; security may move you on.', 'Roadside: park fully off the road.', 'Daytime only.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-the-carding-shed-holmfirth', 'photo', 'The Carding Shed, Holmfirth', 'Cafe at Washpit Mills outside Holmfirth that hosts car meets (including car club BBQ meets) and is listed as a bikers'' stop.', private.pt(53.5573, -1.7852), null, null, null, 'West Yorkshire', array['Private car park: be respectful; security may move you on.', 'Private site; open Wed-Sun daytime.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-doncaster-racecourse-car-park', 'photo', 'Doncaster Racecourse car park', 'Racecourse car park that hosts the AutoCulture car show, which grew out of the Elsecar at the Races enthusiasts'' meet.', private.pt(53.5221, -1.1056), null, null, null, 'South Yorkshire', array['Private car park: be respectful; security may move you on.', 'Event venue; access only on show days or race days.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-elsecar-heritage-centre-car-park', 'photo', 'Elsecar Heritage Centre car park', 'Car park at the restored ironworks and colliery workshops near Barnsley. Car clubs use it as a meeting point before runs to shows.', private.pt(53.4937, -1.4212), null, null, null, 'South Yorkshire', array['Check opening hours; closes in the evening.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-hornbeam-park-harrogate', 'photo', 'Hornbeam Park, Harrogate', 'Business park in Harrogate where a Supercars and Coffee morning has been held outside offices at The Lenz.', private.pt(53.9795, -1.5222), null, null, null, 'North Yorkshire', array['Private car park: be respectful; security may move you on.', 'Private office car parks; only on event mornings.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-rosedale-abbey-village', 'photo', 'Rosedale Abbey village', 'Moors village at the foot of Rosedale Chimney Bank; the Abbey Stores and Tearoom is listed as a bikers'' meeting place.', private.pt(54.3543, -0.8865), null, null, null, 'North Yorkshire', array['Chimney Bank above the village is 1 in 3; closed Wednesdays (tearoom).', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-festival-car-park-skegness', 'photo', 'Festival car park, Skegness', 'Large pay-and-display seafront car park off Tower Esplanade. Police checked around 300 cars at a car meet here on Easter Sunday 2024 and warned drivers over burnouts and donuts.', private.pt(53.1394, 0.3464), null, null, null, 'Lincolnshire', array['Pay and display.', 'Police attend car meets here; Section 59 warnings and seizures have been issued.', 'Main entrance is via Princes Parade.', 'Very busy in summer and on bank holidays.']::text[]),
  ('ps-north-parade-car-park-by-the-pier-skegness', 'photo', 'North Parade car park by the pier, Skegness', 'Pay car park on the seafront by Skegness Pier and the amusements. A biker guide lists the seafront car parks opposite the amusements as a meeting place for bikers.', private.pt(53.145, 0.3467), null, null, null, 'Lincolnshire', array['Pay and display.', 'Police issued anti-social vehicle-use orders after burnouts here in April 2024.', 'Busy in summer.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-gibraltar-point-car-park', 'photo', 'Gibraltar Point car park', 'Lincolnshire Wildlife Trust car park at the Gibraltar Point nature reserve south of Skegness. A biker guide lists the car parks at Gibraltar Point as a meeting place for bikers.', private.pt(53.0972, 0.3226), null, null, null, 'Lincolnshire', array['Parking fee (Wildlife Trust).', 'Nature reserve: keep noise down and stay on the car park.', 'Small car park, about 64 spaces.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-willingham-woods-picnic-site-market-rasen', 'photo', 'Willingham Woods picnic site, Market Rasen', 'Woodland picnic site with a kiosk on the A631 east of Market Rasen. It hosts a long-running Wednesday bike night from April to September and bikers meet here most weekends.', private.pt(53.3806, -0.292), null, null, null, 'Lincolnshire', array['Average speed cameras and a 50 mph limit on the A631 approach.', 'Kiosk open 5pm till dark April to September.', 'Police often attend bike nights.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes); the parking area is not tagged as a car park in OSM; the link goes to the kiosk.']::text[]),
  ('ps-international-bomber-command-centre-car-park-lincoln', 'photo', 'International Bomber Command Centre car park, Lincoln', 'Main car park at the International Bomber Command Centre on Canwick Hill, with the memorial spire and views over Lincoln. Listed by a biker guide as a biker-friendly stop with free motorcycle parking.', private.pt(53.2134, -0.5276), null, null, null, 'Lincolnshire', array['Memorial site: be respectful and quiet.', 'Cafe open Tuesday to Sunday daytime only; check opening times.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-conduit-lane-car-park-grantham', 'photo', 'Conduit Lane car park, Grantham', 'Town centre car park behind the Market Place. At Grantham Bike Night in August 2025 about 800 motorbikes filled the Market Place and spilled into the Conduit Lane car park.', private.pt(52.9129, -0.6452), null, null, null, 'Lincolnshire', array['Bike night is a once-a-year summer event; check the council''s events page for dates.', 'Pay parking in the daytime.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-east-midlands-parkway-station-car-park', 'photo', 'East Midlands Parkway station car park', 'Large railway station car park beside the old Ratcliffe-on-Soar power station site. Around 300 vehicles gathered for a car meet here in April 2021.', private.pt(52.8636, -1.2647), null, null, null, 'Nottinghamshire', array['Private car park: be respectful; security may move you on.', 'Station car park with ANPR paid parking.', 'Police have used dispersal orders here after car meets.', 'Extra traffic rules have been considered around Ratcliffe to stop car meets.']::text[]),
  ('ps-sainsburys-car-park-castle-marina-nottingham', 'photo', 'Sainsbury''s car park, Castle Marina, Nottingham', 'Supermarket car park at Castle Marina near the canal. Nearly 200 car enthusiasts met here after closing time in March 2019 at a modified car meet.', private.pt(52.9457, -1.163), null, null, null, 'Nottinghamshire', array['Private customer car park: the operator issued parking fines to people at the 2019 meet.', 'Residential flats nearby; noise complaints led to action.']::text[]),
  ('ps-ladybower-inn-car-park-a57', 'photo', 'Ladybower Inn car park, A57', 'Pay car park at the Ladybower Inn on the A57 by Ladybower Reservoir, at the eastern end of the Snake Pass. Used as a refreshment stop on motorcycle club rides through the Peak District.', private.pt(53.3747, -1.6939), null, null, null, 'Derbyshire', array['Private car park: be respectful; security may move you on.', 'Pay parking (operator SIP).', 'Mobile speed cameras around Bamford and Ladybower in summer.', 'Busy at weekends.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-tattershall-picnic-site-a153', 'photo', 'Tattershall picnic site, A153', 'Picnic site with a cafe on Sleaford Road at Tattershall. A biker guide lists it as a meeting place for bikers in Lincolnshire.', private.pt(53.097, -0.204), null, null, null, 'Lincolnshire', array['Roadside: park fully off the road.', 'Car park open 08:00 to 20:00.', 'Cafe open daily 8.30 to 3.30.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-ship-inn-car-park-fosdyke-bridge', 'photo', 'Ship Inn car park, Fosdyke Bridge', 'Pub car park beside the A17 bridge over the River Welland at Fosdyke. The pub runs a monthly summer bike night for motorcycles.', private.pt(52.87, -0.0415), null, null, null, 'Lincolnshire', array['Private car park: be respectful; security may move you on.', 'Pub car park: be a customer.', 'Bike night is the third Thursday of the month in summer; the pub opens Wednesday to Sunday.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-sainsburys-car-park-melton-road-leicester', 'photo', 'Sainsbury''s car park, Melton Road, Leicester', 'Large supermarket car park on Melton Road in Rushey Mead. Leicestershire Police list car meets at this Sainsbury''s as a local priority.', private.pt(52.668, -1.1059), null, null, null, 'Leicestershire', array['Private customer car park.', 'Police patrol for car meets, anti-social driving and speeding here.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-prince-consort-road-parking-exhibition-road', 'photo', 'Prince Consort Road parking, Exhibition Road', 'On-street pay-and-display bays by Prince Consort Road, at the Exhibition Road end in South Kensington. Councils and police name Exhibition Road and Prince Consort Road as a monthly car meet spot for supercars and high-performance cars, with up to 100 or more cars.', private.pt(51.4999, -0.1758), null, null, null, 'Greater London', array['Roadside: park fully off the road.', 'High Court injunction (June 2026) bans car meets in Brompton and Hans Town ward, including Exhibition Road, 6pm to 7am: https://www.rbkc.gov.uk/newsroom/high-court-injunction-targets-nuisance-car-meets-kensington-and-chelsea.', 'Pay-and-display on-street bays, only about 20 spaces.', 'Regular police patrols and section 59 warnings.']::text[]),
  ('ps-grosvenor-hill-ncp-for-berkeley-square', 'photo', 'Grosvenor Hill NCP, for Berkeley Square', 'NCP car park a short walk from Berkeley Square in Mayfair, a well-known supercar spotting street. Berkeley Square hosted H.R. Owen''s Supercar Sunday, and Autocar''s car-spotting feature found supercars there.', private.pt(51.5112, -0.1463), null, null, null, 'Greater London', array['Private car park: be respectful; security may move you on.', 'Expensive central London NCP; motorbike bays on Berkeley Square itself.', 'Westminster car meet injunction and proposed PSPO extension cover Mayfair: no revving or meets.', 'Supercar spotting is on foot; Berkeley Square is a public street, not a meet venue.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-battersea-park-chelsea-gate-car-park-chelsea-bridge', 'photo', 'Battersea Park (Chelsea Gate) car park, Chelsea Bridge', 'Pay car park in Battersea Park near the south end of Chelsea Bridge. Since the 1950s the bridge has been a Friday-night meeting place for motorcyclists, and bikers are reported to still meet there.', private.pt(51.4826, -0.1546), null, null, null, 'Greater London', array['Pay parking; park gates and car park close at night, so check times.', 'Meets now much smaller than in the past; residents have complained about racing noise.', 'The bridge is lit at night; photos from the Embankment pavements.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-beckton-retail-park-car-park', 'photo', 'Beckton Retail Park car park', 'Retail park car park off Royal Albert Way in Beckton. Newham Council and the Met shut down two illegal car meets of up to 100 drivers here in September 2021.', private.pt(51.5169, 0.0619), null, null, null, 'Greater London', array['Private car park: be respectful; security may move you on.', 'Private retail car park: customers only, may be closed or patrolled after hours.', 'Police and council have seized cars at meets here.']::text[]),
  ('ps-hayes-bridge-retail-park-car-park', 'photo', 'Hayes Bridge Retail Park car park', 'Retail park car park on Uxbridge Road at Hayes Bridge. It hosted a monthly West London car meet that police broke up in 2017, and further car meets were reported in 2018.', private.pt(51.5127, -0.3939), null, null, null, 'Greater London', array['Private car park: be respectful; security may move you on.', 'Gates reported locked every night since 2018.', 'Hillingdon car meets PSPO (2025) may apply: https://www.hillingdon.gov.uk/pspo.', 'Private retail car park: customers only.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-crystal-palace-park-car-park', 'photo', 'Crystal Palace Park car park', 'Free public car park in Crystal Palace Park, home of the old motor racing circuit. The park hosted Motorsport at the Palace, with historic racing cars and classic car club displays.', private.pt(51.4213, -0.0718), null, null, null, 'Greater London', array['Park car parks may close at dusk.', 'Motorsport at the Palace has not been confirmed as running in recent years.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-tower-retail-park-car-park-crayford', 'photo', 'Tower Retail Park car park, Crayford', 'Retail park car park on Crayford Road, Crayford. A car cruise group held Thursday-night car meets here and at the nearby Sainsbury''s car park, leading to police raids.', private.pt(51.4508, 0.1814), null, null, null, 'Greater London', array['Private car park: be respectful; security may move you on.', 'Private retail car park: customers only.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes); evidence is old (2004); no recent meets confirmed.']::text[]),
  ('ps-argall-way-car-park-leyton', 'photo', 'Argall Way car park, Leyton', 'Public pay car park by Argall Way industrial estate near Lea Bridge station. Local press describes Argall Way as a popular car meets site, and Lea Bridge is one of the borough''s main car meet hotspots.', private.pt(51.5692, -0.0403), null, null, null, 'Greater London', array['Waltham Forest car meets PSPO (from October 2024) applies borough-wide: https://www.walthamforest.gov.uk/neighbourhoods/crime-and-community-safety/public-space-protection-orders.', 'Industrial estate: working vehicles by day.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-tesco-elmers-end-car-park', 'photo', 'Tesco Elmers End car park', 'Superstore car park on Croydon Road, Elmers End. It has had repeated late-night car meets with drifting, prompting a residents'' petition and new barriers.', private.pt(51.3978, -0.049), null, null, null, 'Greater London', array['Private car park: be respectful; security may move you on.', 'Barriers and nightly fencing now block the car park outside opening hours.', 'Customers only; homes close by, so keep noise down.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-tesco-extra-car-park-beverley-way-new-malden', 'photo', 'Tesco Extra car park, Beverley Way, New Malden', 'Large superstore car park beside the A3 at New Malden. The Met appealed for information after a car meet here on 15 August 2026.', private.pt(51.4015, -0.2396), null, null, null, 'Greater London', array['Private car park: be respectful; security may move you on.', 'Customers only; police are investigating dangerous driving linked to meets here.', 'Busy A3 junction next to the car park.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-bell-street-quayside-parking-north-shields-fish-quay', 'photo', 'Bell Street quayside parking, North Shields Fish Quay', 'Pay parking bays on Bell Street by the Fish Quay on the Tyne. Porsche Club GB members held a Sunday car meet in the Bell Street quayside car park, and classic car shows have been held at the nearby Fish Quay Heritage Centre and Clifford''s Fort.', private.pt(55.0083, -1.4374), null, null, null, 'Tyne and Wear', array['Pay parking; small street-side bays that fill on busy weekends.', 'Busy fish quay with restaurants; keep noise down in the evening.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-durham-city-retail-park-sunderland-road', 'photo', 'Durham City Retail Park, Sunderland Road', 'Free retail park car park on Sunderland Road at Gilesgate Moor, near Dragonville. Durham Special Constabulary road policing officers attended a car meet gathering here in February 2019 and warned drivers about anti-social behaviour.', private.pt(54.7818, -1.537), null, null, null, 'County Durham', array['Private car park: be respectful; security may move you on.', 'Private retail car park; follow site rules and leave when shops close.', 'Police have attended meets here and warned about revving, tyre spinning and illegal plates and lights.']::text[]),
  ('ps-prince-bishops-car-park-durham-city-centre', 'photo', 'Prince Bishops car park, Durham city centre', 'Council-run multi-deck car park under the Prince Bishops shopping centre in Durham city centre. A North East Saab club car meet was held on deck 6 in March 2025, listed by Visit County Durham.', private.pt(54.7771, -1.5738), null, null, null, 'County Durham', array['Pay parking; check opening hours, the car park may close overnight.', 'Low headroom in covered decks.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-prudhoe-tyneview-retail-park', 'photo', 'Prudhoe (Tyneview) Retail Park', 'Retail park on the A695 at Prudhoe with McDonald''s, Greggs and Caffe Ginevra. Hundreds of drivers came to a car meet here in May 2022 and Northumbria Police sent a police plane; Porsche Club members have also held cars and coffee meets at the cafe.', private.pt(54.969, -1.8369), null, null, null, 'Northumberland', array['Private car park: be respectful; security may move you on.', 'Private customer car park; Northumbria Police have warned that cars at unauthorised meets here could be seized.', 'Keep meets static and quiet; residents nearby have complained about speeding.']::text[]),
  ('ps-allensford-park-car-park-consett', 'photo', 'Allensford Park car park, Consett', 'Free car park at Allensford Park by the River Derwent on the A68 near Consett. The Biker Guide lists the cafe here as a regular meeting place for bikers.', private.pt(54.8466, -1.8804), null, null, null, 'County Durham', array['Country park car park; can be busy on sunny weekends.', 'Cafe hours vary; check before riding out.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-ok-diner-a19-southbound-elwick', 'photo', 'OK Diner, A19 southbound, Elwick', 'American-style diner at the A19 southbound services near Hartlepool. The Biker Guide lists it as a meeting place for bikers in County Durham.', private.pt(54.656, -1.303), null, null, null, 'County Durham', array['Private car park: be respectful; security may move you on.', 'Roadside: park fully off the road.', 'Customer car park at a roadside services; southbound carriageway only.', 'Diner listed as open 9am to 8pm; check current hours.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-middleton-in-teesdale-short-stay-car-park', 'photo', 'Middleton-in-Teesdale short stay car park', 'Free short stay car park on Bridge Street in Middleton-in-Teesdale, opposite the Tees''pot cafe. The Biker Guide lists the cafe as a bikers'' meeting place, and BestBikingRoads riders recommend stopping here for a cuppa on the B6276 and B6277.', private.pt(54.6238, -2.0827), null, null, null, 'County Durham', array['Short stay only; small village car park that fills on summer weekends.', 'Moorland roads either side have sheep, ice in winter and regular speed checks.']::text[]),
  ('ps-amble-harbour-car-park', 'photo', 'Amble harbour car park', 'Pay car park by Amble Harbour Village on the Coquet estuary. Around 430 motorbikes on the Northumbria Easter Egg Run paraded down Queen Street and stopped at the harbour to meet the public in 2023, and the run stops here most years.', private.pt(55.3358, -1.5803), null, null, null, 'Northumberland', array['Pay parking; very busy on Easter Saturday and summer weekends.']::text[]),
  ('ps-south-promenade-car-park-gypsies-green-south-shields', 'photo', 'South Promenade car park, Gypsies Green, South Shields', 'Seafront pay car park on Sea Road next to Gypsies Green. The North East American Car Club holds its Fins and Chrome classic car show on Gypsies Green, with American and British classic cars on display, and tells visitors to use the seafront car parks.', private.pt(54.9967, -1.41), null, null, null, 'Tyne and Wear', array['Pay parking; very busy on summer weekends and bank holidays.', 'The show is on the grass next door, not in the car park itself.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-seaburn-park-car-park-whitburn-road', 'photo', 'Seaburn Park car park, Whitburn Road', 'Seafront car park beside Seaburn Recreation Park in Sunderland. The recreation park hosts the annual Seaburn vintage vehicle rally and the Sunderland and District Classic Vehicle Society''s classic car show.', private.pt(54.9327, -1.3676), null, null, null, 'Tyne and Wear', array['Check parking charges on the seafront; busy in summer.', 'Shows are held on the grass of the recreation park next door.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-station-yard-car-park-seahouses', 'photo', 'Station Yard car park, Seahouses', 'Main council car park in Seahouses, a short walk from the harbour and Farne Islands boats. A 2023 travel blog describes the village car park filled with at least 50 Harley-Davidson motorbikes on a September Sunday.', private.pt(55.5809, -1.6559), null, null, null, 'Northumberland', array['Pay parking 8am to 6pm; free overnight.', 'Very busy in summer; parking wardens patrol.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-bassetts-pole-inn-car-park-a38-a446', 'photo', 'Bassetts Pole Inn car park (A38/A446)', 'Pub car park at the Bassetts Pole junction near Sutton Coldfield. The Biker Guide lists it as busy with bikers through the summer, with one of the biggest bike meets in the country on Tuesday evenings.', private.pt(52.5914, -1.7815), null, null, null, 'Staffordshire', array['Private car park: be respectful; security may move you on.', 'Customer car park: buy something and check the Tuesday bike meet is still running before travelling.', 'Sits on the Staffordshire/Warwickshire border next to a busy trunk-road junction.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-hatton-country-world-events-area-car-park', 'photo', 'Hatton Country World events area car park', 'Car park at Hatton Country World near Warwick. The Biker Guide says the long-running Wednesday evening motorcycle meets moved here from the Hatton Arms, using the events area after the shops close.', private.pt(52.2943, -1.6555), null, null, null, 'Warwickshire', array['Private car park: be respectful; security may move you on.', 'Private attraction car park: the bike meet is seasonal, check dates before going.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-linkway-retail-park-cannock', 'photo', 'Linkway Retail Park, Cannock', 'Retail park car park at Longford Island (A5/A4601) in Cannock. Cannock Chase Council says police identified it as a hotspot for car meets and racing, leading to joint enforcement in 2026.', private.pt(52.6787, -2.0475), null, null, null, 'Staffordshire', array['Private car park: be respectful; security may move you on.', 'ANPR and CCTV cameras installed across the retail park in 2026; police and council have issued Public Space Protection Order warnings to car meet attendees.', 'Customer parking for the shops: no racing, revving or loitering after hours.']::text[]),
  ('ps-wyrley-brook-retail-park-b-q-cannock', 'photo', 'Wyrley Brook Retail Park (B&Q), Cannock', 'B&Q car park on Wyrley Brook Retail Park, Vine Lane, Bridgtown. Express & Star reported police finding an organised early-morning car meet here in May 2024.', private.pt(52.6754, -2.0335), null, null, null, 'Staffordshire', array['Private car park: be respectful; security may move you on.', 'Police have attended reports of dangerous driving at meets here; Cannock Chase has a Public Space Protection Order covering car cruising (see https://cannockchasedc.gov.uk/node/8719).', 'Customer car park.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-tesco-car-park-victoria-street-hednesford', 'photo', 'Tesco car park, Victoria Street, Hednesford', 'Supermarket car park in Hednesford town centre. Express & Star has reported repeated night-time car gatherings here, including a police call-out in May 2024 and an earlier crackdown on boy racers that closed the car park on Sunday nights.', private.pt(52.7116, -1.9988), null, null, null, 'Staffordshire', array['Private car park: be respectful; security may move you on.', 'Customer car park; it has been closed at night in the past to stop car meets.', 'Cannock Chase car cruising PSPO warnings are issued in the district (https://cannockchasedc.gov.uk/node/8719).', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-old-rose-crown-car-park-stourport-on-severn', 'photo', 'Old Rose & Crown car park, Stourport-on-Severn', 'Pub on the Worcester Road outside Stourport with a flat car park overlooked by seating. The Biker Guide lists it as motorcycle friendly every day, with a retro bike night on Fridays from April to October.', private.pt(52.336, -2.2686), null, null, null, 'Worcestershire', array['Private car park: be respectful; security may move you on.', 'Customer car park.', 'Bike night is seasonal (April to October); check before travelling.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-the-talbot-car-park-knightwick-a44', 'photo', 'The Talbot car park, Knightwick (A44)', 'Pub car park by the River Teme bridge at Knightwick on the A44 Worcester to Bromyard road. The Biker Guide lists a bike night here every other Tuesday from April to October.', private.pt(52.2016, -2.3913), null, null, null, 'Worcestershire', array['Private car park: be respectful; security may move you on.', 'Customer car park.', 'Bike nights are fortnightly and seasonal; check dates first.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-the-winking-man-car-park-upper-hulme-a53', 'photo', 'The Winking Man car park, Upper Hulme (A53)', 'Pub car park high on the A53 Leek to Buxton road below Ramshaw Rocks. The Biker Guide lists it as a biker-friendly meeting place, and BestBikingRoads riders route through it.', private.pt(53.1708, -1.9622), null, null, null, 'Staffordshire', array['Private car park: be respectful; security may move you on.', 'Customer car park on an exposed moorland road: ice and fog in winter.', 'The A53 is heavily policed for speed.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-black-horse-car-park-illey', 'photo', 'Black Horse car park, Illey', 'Country pub car park on Illey Lane on the edge of Halesowen. The Biker Guide lists a weekly bike night here on Monday evenings from 7pm.', private.pt(52.4336, -2.0273), null, null, null, 'West Midlands', array['Private car park: be respectful; security may move you on.', 'Customer car park; narrow country lane access.', 'Inside the Birmingham/Black Country car cruising injunction area: bike night yes, cruising no.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
  ('ps-arrow-mill-car-park-alcester', 'photo', 'Arrow Mill car park, Alcester', 'Car park at the Arrow Mill hotel on the River Arrow south of Alcester. The Biker Guide lists informal bike meets here from 3pm every Sunday.', private.pt(52.2032, -1.8808), null, null, null, 'Warwickshire', array['Private car park: be respectful; security may move you on.', 'Hotel customer car park: buy something and check the Sunday bike meet is still running.', 'Medium confidence: the position or details are not confirmed for 2026 (research notes).']::text[]),
